{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "UK-224,671, the highest-transfer analogue, had only 7.5% oral bioavailability in fasted humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "MK-458, a fused phenolic amine, had absolute oral bioavailability of approximately 5% in patients, supporting poor absorption for this rigid phenolic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Rotigotine, a phenolic tertiary amine with a fused ring system, has low oral bioavailability in humans, consistent with poor absorption of this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Dihydrexidine, a rigid catechol/amine dopamine agonist, exhibited low oral bioavailability, reinforcing the poor oral absorption of rigid polar aminergic scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Catechin, a high-transfer polyphenol, had only about 1.68% oral bioavailability in humans, indicating that polar phenolic compounds in this transfer range are poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Pethidine, a smaller tertiary amine, had about 56% oral bioavailability, but it lacks the permanent quaternary ammonium and rigid polar morphinan core of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%) because the query is a quaternary ammonium morphinan with a phenol and polar ketone/alcohol; the highest-transfer analogues (UK-224,671, MK-458, rotigotine, dihydrexidine, catechins) all show F below 10%, and the permanent positive charge is a major barrier to passive absorption. The few high-F basic amines lack the quaternary charge and rigid polar scaffold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself; extrapolation relies on transferable analogues.",
    "The query's permanent quaternary ammonium is a stronger absorption barrier than most analogues, so quantitative F may be even lower than the analogue values.",
    "Some high-F analogues (e.g., pethidine) are structurally distant and do not capture the quaternary charge."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

